const armoredTurtleSheet=new Image();armoredTurtleSheet.assetSrc='assets/armored-turtle-v2.png';
function beginArmoredTurtle(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'turtleRetaliation',bespoke:true,windup:2,origin:{x:e.x,y:e.y},angle,charge:0,fired:false};}
function armoredTurtleGuard(e){let a=e.attack;return e.hp>0&&!(e.reactionStun>0)&&a?.pattern==='turtleRetaliation'&&e.elapsed<2&&!a.fired&&dist(e,a.origin)<=24;}
const armoredTurtleHitBase=hit;hit=(e,d)=>{let a=e.attack,hp=e.hp,guard=e.species==='r8e4'&&!e.dotTick&&armoredTurtleGuard(e);let result=armoredTurtleHitBase(e,d*(guard?.3:1));if(guard&&e.hp>0&&e.attack===a)a.charge=Math.min(80,a.charge+Math.max(0,hp-e.hp)*.1);return result;};
const armoredTurtleAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r8e4')return armoredTurtleAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='turtleRetaliation'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=230&&clear){beginArmoredTurtle(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,48*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,20)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=2){a.fired=true;e.struck=true;if(dist(p,a.origin)<=220+1e-8&&lineClear(a.origin,p))hurt(58+a.charge);playSound('impact',e.x,e.y);burst(e.x,e.y,90,'#8ed6da');}
 if(e.elapsed>=4.5){e.attack=null;e.state='idle';e.t=2.5;}
};
const armoredTurtleDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r8e4'||!armoredTurtleSheet.complete||!armoredTurtleSheet.naturalWidth||!armoredTurtleSheet.naturalHeight)return armoredTurtleDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='turtleRetaliation')f={row:2,col:e.elapsed<.45?0:e.elapsed<2?1:e.elapsed<2.35?2:3};let q=project(e.x,e.y),sw=armoredTurtleSheet.naturalWidth/4,sh=armoredTurtleSheet.naturalHeight/3,w=300,h=w*sh/sw,anchor=[.84,.87,.88][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,armoredTurtleSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(armoredTurtleSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const armoredTurtleSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r8e4'?190:armoredTurtleSizeBase(e);
const armoredTurtleGroundBase=drawGroundEffects;drawGroundEffects=()=>{armoredTurtleGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r8e4'):enemies)){let a=e.attack;if(e.species!=='r8e4'||e.hp<=0||a?.pattern!=='turtleRetaliation'||!visibleAt(e.x,e.y))continue;if(e.elapsed>=2.35){groundRing(e.x,e.y,40,'#9bddcf',2);continue;}groundRing(a.origin.x,a.origin.y,220,a.fired?'#d9ffff':'#75bdc7',a.fired?4:1);if(!a.fired){groundRing(e.x,e.y,45,'#8ed6da',3);if(a.charge>0)groundRing(e.x,e.y,55+a.charge*.4,'#efb774',2);}}};
